import{_ as a,o,c as e,ag as n}from"./chunks/framework.i8sMDeRW.js";const h=JSON.parse('{"title":"OpenFoodData 案例：营养数据平台的产品决策复盘","description":"","frontmatter":{},"headers":[],"relativePath":"guide/03-cases/openfooddata-case-study.md","filePath":"guide/03-cases/openfooddata-case-study.md","lastUpdated":1778767928000}'),r={name:"guide/03-cases/openfooddata-case-study.md"};function s(l,t,i,d,p,u){return o(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="openfooddata-案例-营养数据平台的产品决策复盘" tabindex="-1">OpenFoodData 案例：营养数据平台的产品决策复盘 <a class="header-anchor" href="#openfooddata-案例-营养数据平台的产品决策复盘" aria-label="Permalink to &quot;OpenFoodData 案例：营养数据平台的产品决策复盘&quot;">​</a></h1><blockquote><p><strong>一句话定位</strong>：面向健康饮食研究者的结构化营养数据平台，追求数据质量的深度控制而非数据量的无限增长。</p></blockquote><h2 id="一、项目背景与缘起" tabindex="-1">一、项目背景与缘起 <a class="header-anchor" href="#一、项目背景与缘起" aria-label="Permalink to &quot;一、项目背景与缘起&quot;">​</a></h2><h3 id="_1-1-为什么做这个产品" tabindex="-1">1.1 为什么做这个产品 <a class="header-anchor" href="#_1-1-为什么做这个产品" aria-label="Permalink to &quot;1.1 为什么做这个产品&quot;">​</a></h3><p>市面上不缺营养数据工具——MyFitnessPal、FatSecret、OpenFoodFacts 都有海量数据。但它们普遍面向&quot;条码扫描 + 热量记录&quot;场景，存在几个共性问题：</p><ul><li><strong>数据质量不可控</strong>：众包（UGC）模式导致数据完整性和准确性参差不齐</li><li><strong>搜索范式单一</strong>：以品牌商品搜索为主，缺乏&quot;标准品优先&quot;的搜索体验</li><li><strong>评分体系缺失</strong>：没有统一的营养质量评分，用户无法横向比较</li><li><strong>加工关系模糊</strong>：苹果和苹果汁的关系、鸡胸肉和水煮鸡胸肉的关系没有被建模</li><li><strong>数据来源不透明</strong>：不知道数据到底来自 USDA 还是用户手动输入</li></ul><p><strong>产品核心假设</strong>：存在一个未被充分服务的用户群体——他们不是想记录&quot;今天吃了多少卡路里&quot;，而是想理解&quot;哪些食物在某个营养维度上表现更好&quot;。</p><h3 id="_1-2-竞品定位差异" tabindex="-1">1.2 竞品定位差异 <a class="header-anchor" href="#_1-2-竞品定位差异" aria-label="Permalink to &quot;1.2 竞品定位差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>OpenFoodData</th><th>OpenFoodFacts / MyFitnessPal</th></tr></thead><tbody><tr><td>数据来源</td><td>政府权威数据库（USDA、中国食物成分表）</td><td>用户众包 + 品牌提交</td></tr><tr><td>搜索范式</td><td>标准品优先（苹果 → 富士苹果）</td><td>条码扫描、品牌名称</td></tr><tr><td>评分体系</td><td>四层权威分级 + 多维度评分</td><td>无统一评分</td></tr><tr><td>加工关系</td><td>模型化（苹果 → 苹果汁、苹果酱）</td><td>无独立建模</td></tr><tr><td>数据质量</td><td>来源权威分、冲突检测、置信度</td><td>依赖用户投票</td></tr></tbody></table><hr><h2 id="二、产品定位决策" tabindex="-1">二、产品定位决策 <a class="header-anchor" href="#二、产品定位决策" aria-label="Permalink to &quot;二、产品定位决策&quot;">​</a></h2><h3 id="_2-1-核心价值主张" tabindex="-1">2.1 核心价值主张 <a class="header-anchor" href="#_2-1-核心价值主张" aria-label="Permalink to &quot;2.1 核心价值主张&quot;">​</a></h3><blockquote><p>不做&quot;热量记录工具&quot;，而是做&quot;食物营养知识库&quot;。</p></blockquote><p>OpenFoodData 追求的是：<strong>当你想知道&quot;低糖水果有哪些&quot;或&quot;哪种食物蛋白质密度最高&quot;时，给你一个可靠、透明、结构化的答案。</strong></p><h3 id="_2-2-目标用户" tabindex="-1">2.2 目标用户 <a class="header-anchor" href="#_2-2-目标用户" aria-label="Permalink to &quot;2.2 目标用户&quot;">​</a></h3><ul><li><strong>健康饮食研究者</strong>：想了解食物营养构成的系统性知识</li><li><strong>减脂/控糖人群</strong>：需要比较不同食物的营养指标</li><li><strong>营养师/健身教练</strong>：需要权威、可引用的营养数据</li><li><strong>食品科技从业者</strong>：需要结构化的食物营养数据库</li></ul><h3 id="_2-3-不做的事情" tabindex="-1">2.3 不做的事情 <a class="header-anchor" href="#_2-3-不做的事情" aria-label="Permalink to &quot;2.3 不做的事情&quot;">​</a></h3><ul><li><strong>不做条码扫描</strong>——不追品牌级数据覆盖，聚焦食材级知识</li><li><strong>不做饮食记录</strong>——不是 MyFitnessPal 的替代品</li><li><strong>不做医学建议</strong>——所有评分标注 disclaimer</li></ul><hr><h2 id="三、核心产品决策复盘" tabindex="-1">三、核心产品决策复盘 <a class="header-anchor" href="#三、核心产品决策复盘" aria-label="Permalink to &quot;三、核心产品决策复盘&quot;">​</a></h2><h3 id="决策-1-搜索范式-——-标准品优先" tabindex="-1">决策 1：搜索范式 —— 标准品优先 <a class="header-anchor" href="#决策-1-搜索范式-——-标准品优先" aria-label="Permalink to &quot;决策 1：搜索范式 —— 标准品优先&quot;">​</a></h3><p><strong>决策内容</strong>：搜索以 Canonical Food（标准品）为第一优先级，再展示 Variant（品种变体）和 Source Food（来源食品行）。</p><p><strong>搜索优先级</strong>：</p><ol><li>Canonical Food 的名称匹配</li><li>Variant 的关联匹配</li><li>原始 Source Food 的模糊匹配</li></ol><p><strong>为什么这样选</strong>：</p><p>用户搜索&quot;苹果&quot;时，想要的是关于&quot;苹果&quot;这种食物的完整营养信息，而不是&quot;某个超市品牌的某款苹果&quot;。标准品优先让搜索结果符合用户意图。</p><p><strong>替代方案 vs 选择理由</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>问题</th></tr></thead><tbody><tr><td>品牌商品优先</td><td>搜索&quot;牛奶&quot;出来 100 个品牌，信息噪音大</td></tr><tr><td>混合无排序</td><td>标准品和品牌混在一起，无法快速定位</td></tr><tr><td>标准品优先（选择）</td><td>先给&quot;牛奶&quot;的完整画像，品牌作为补充</td></tr></tbody></table><p><strong>效果</strong>：搜索体验更接近&quot;维基百科&quot;而非&quot;电商搜索&quot;。</p><h3 id="决策-2-数据质量体系-——-权威等级-加权聚合" tabindex="-1">决策 2：数据质量体系 —— 权威等级 + 加权聚合 <a class="header-anchor" href="#决策-2-数据质量体系-——-权威等级-加权聚合" aria-label="Permalink to &quot;决策 2：数据质量体系 —— 权威等级 + 加权聚合&quot;">​</a></h3><p><strong>决策内容</strong>：建立 A/B/C/D 四层权威等级体系，采用加权平均聚合多源数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A: 原始营养数据          energy_kcal, protein, total_fat...</span></span>
<span class="line"><span>                         (政府数据库级别)</span></span>
<span class="line"><span>B: 标准衍生指标          salt_equivalent, protein_density, GL</span></span>
<span class="line"><span>C: 规则分级指标          sugar_level, sodium_level</span></span>
<span class="line"><span>D: 产品评分指标          diabetes_friendly_score, weight_loss_friendly_score...</span></span>
<span class="line"><span>                         ⚠️ 强制标注 disclaimer</span></span></code></pre></div><p><strong>加权聚合策略</strong>：</p><ul><li>每个 <code>DataSource</code> 有 <code>authority_score</code>（默认 0.8）</li><li>代表值 = Σ(值 × 权重) / Σ(权重)</li><li>置信度 = min(0.95, 0.7 + 0.05 × 来源数)</li><li>争议标记：当 max-min &gt; |均值| × 30% 时，标记 <code>is_contested = true</code></li></ul><p><strong>为什么这样选</strong>：</p><p>多源数据必然存在冲突——USDA 和中国食物成分表对同一食物的营养值可能有差异。简单的取平均或取最新都不够好。加权聚合让更权威的来源有更大话语权，同时置信度和争议标记让用户了解数据的可靠性。</p><h3 id="决策-3-评分方法论-——-可解释的公式-而非黑盒" tabindex="-1">决策 3：评分方法论 —— 可解释的公式，而非黑盒 <a class="header-anchor" href="#决策-3-评分方法论-——-可解释的公式-而非黑盒" aria-label="Permalink to &quot;决策 3：评分方法论 —— 可解释的公式，而非黑盒&quot;">​</a></h3><p><strong>决策内容</strong>：所有评分（D 级）使用明确的数学公式，而非 ML 模型。</p><p><strong>示例评分公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>控糖友好分 = 5 + 纤维×0.5 - 糖/10 + GI奖励 + GL奖励 + 热量密度奖励</span></span>
<span class="line"><span></span></span>
<span class="line"><span>减脂友好分 = 5 + 能量奖励 + 纤维×0.5 - 糖/10 + 蛋白质×0.3 + 脂肪奖励</span></span>
<span class="line"><span></span></span>
<span class="line"><span>饱腹感分   = 3 + 蛋白质×0.3 + 纤维×0.4 + 水/40 + 能量奖励</span></span></code></pre></div><p><strong>为什么这样选</strong>：</p><ol><li><strong>可解释性</strong>：用户能理解&quot;我为什么得了这个分数&quot;，而不是面对一个魔法数字</li><li><strong>可调性</strong>：产品经理可以直接调整公式参数，无需模型训练</li><li><strong>免责安全</strong>：公式给出的是&quot;基于公开营养数据的参考评分&quot;，而非&quot;医学建议&quot;</li></ol><p><strong>效果</strong>：用户可以在详情页看到评分的具体构成，增强了信任。</p><h3 id="决策-4-加工关系建模-——-独立-canonical-而非属性标签" tabindex="-1">决策 4：加工关系建模 —— 独立 canonical 而非属性标签 <a class="header-anchor" href="#决策-4-加工关系建模-——-独立-canonical-而非属性标签" aria-label="Permalink to &quot;决策 4：加工关系建模 —— 独立 canonical 而非属性标签&quot;">​</a></h3><p><strong>决策内容</strong>：加工食品（苹果汁）作为独立的 Canonical Food，通过 <code>FoodProcessingRelation</code> 表与原材关联。</p><p><strong>为什么这样选</strong>：</p><p><strong>错误方案</strong>：给&quot;苹果&quot;加一个&quot;加工形态：果汁&quot;的属性。</p><p>问题是：苹果汁的营养构成和苹果完全不同（糖浓度、纤维、维生素 C 等），把它当作&quot;苹果&quot;的一个属性会污染数据。</p><p><strong>正确选择</strong>：苹果汁是独立的食物实体，通过 <code>processed_from</code> 关系与苹果关联。这保持了两个实体的营养数据独立性，同时保留了&quot;它们有关系&quot;的信息。</p><h3 id="决策-5-品种-variant-vs-独立-canonical" tabindex="-1">决策 5：品种（Variant） vs 独立 Canonical <a class="header-anchor" href="#决策-5-品种-variant-vs-独立-canonical" aria-label="Permalink to &quot;决策 5：品种（Variant） vs 独立 Canonical&quot;">​</a></h3><p><strong>决策内容</strong>：富士苹果和嘎啦苹果是&quot;苹果&quot;的 Variant，而非独立 Canonical Food。</p><p><strong>为什么这样选</strong>：</p><p>富士和嘎啦的营养差异很小（主要是糖度微差），如果各自作为独立 canonical，会让搜索结果充斥着&quot;苹果 × N&quot;的噪音。Variant 模式在&quot;展示品种差异&quot;和&quot;保持搜索简洁&quot;之间取得平衡。</p><h3 id="决策-6-缺失值显示-null-而非-0" tabindex="-1">决策 6：缺失值显示 null 而非 0 <a class="header-anchor" href="#决策-6-缺失值显示-null-而非-0" aria-label="Permalink to &quot;决策 6：缺失值显示 null 而非 0&quot;">​</a></h3><p><strong>决策内容</strong>：营养数据缺失时显示 <code>null</code>，而非 <code>0</code>。</p><p><strong>为什么这样选</strong>：</p><p>显示 <code>0</code> 会让用户误以为&quot;这种食物不含该营养素&quot;。显示 <code>null</code> 表示&quot;我们没有这个数据&quot;，避免了误导。这是一个看似微小但影响信任的设计决策。</p><h3 id="决策-7-api-设计-——-胖详情-api" tabindex="-1">决策 7：API 设计 —— 胖详情 API <a class="header-anchor" href="#决策-7-api-设计-——-胖详情-api" aria-label="Permalink to &quot;决策 7：API 设计 —— 胖详情 API&quot;">​</a></h3><p><strong>决策内容</strong>：食物详情 API 一次请求返回全部数据（基本信息、摘要指标、全量营养表、评分、排行榜、变体、来源）。</p><p><strong>为什么这样选</strong>：</p><ul><li>减少前端多次请求（适合移动端）</li><li>简化前端状态管理</li><li>单请求即可渲染完整页面</li></ul><p><strong>权衡</strong>：对后端性能要求更高，每次请求都需要聚合多张表的数据。当前数据量下可行，未来可能需要缓存策略。</p><h3 id="决策-8-基础设施预留而非预埋" tabindex="-1">决策 8：基础设施预留而非预埋 <a class="header-anchor" href="#决策-8-基础设施预留而非预埋" aria-label="Permalink to &quot;决策 8：基础设施预留而非预埋&quot;">​</a></h3><p><strong>决策内容</strong>：Elasticsearch 和 Redis 已在 docker-compose 中定义但<strong>未实际接入</strong>代码。</p><p><strong>为什么这样选</strong>：</p><p>当前数据量下，PostgreSQL ILIKE 搜索和直接查询即可满足性能需求。过早引入 Elasticsearch 和 Redis 增加了运维复杂度（索引管理、缓存失效等），而收益不明显。</p><p><strong>预留策略的好处</strong>：</p><ul><li>docker-compose 已定义 → 未来接入只需改几行代码</li><li>没有引入不必要的复杂度</li><li>开发环境无需启动额外服务</li></ul><hr><h2 id="四、踩坑与教训" tabindex="-1">四、踩坑与教训 <a class="header-anchor" href="#四、踩坑与教训" aria-label="Permalink to &quot;四、踩坑与教训&quot;">​</a></h2><h3 id="坑-1-多源数据冲突比预期严重" tabindex="-1">坑 1：多源数据冲突比预期严重 <a class="header-anchor" href="#坑-1-多源数据冲突比预期严重" aria-label="Permalink to &quot;坑 1：多源数据冲突比预期严重&quot;">​</a></h3><p>不同政府的食物数据库对同一食物的营养值可能有 20-30% 的差异。例如 USDA 和日本食物成分表对&quot;鸡蛋&quot;的蛋白质含量定义不同（是否包含蛋壳重量？计算基准是否一致？）。</p><p><strong>教训</strong>：需要建立更精细的 <code>NutrientMapping</code> 机制，不只是映射营养素编码，还要理解不同数据库的<strong>测量基准差异</strong>。</p><h3 id="坑-2-聚合层的滞后效应" tabindex="-1">坑 2：聚合层的滞后效应 <a class="header-anchor" href="#坑-2-聚合层的滞后效应" aria-label="Permalink to &quot;坑 2：聚合层的滞后效应&quot;">​</a></h3><p><code>RepresentativeNutrientValue</code> 基于多源加权平均，但导入新数据源后需要重新计算所有代表值。当前没有自动触发重新计算的机制。</p><p><strong>待解决问题</strong>：需要建立代表值更新的事件驱动机制，或者定期批量重算。</p><h3 id="坑-3-displayprofile-已设计未实现" tabindex="-1">坑 3：DisplayProfile 已设计未实现 <a class="header-anchor" href="#坑-3-displayprofile-已设计未实现" aria-label="Permalink to &quot;坑 3：DisplayProfile 已设计未实现&quot;">​</a></h3><p>模型中定义了 <code>DisplayProfile</code>（用户偏好配置），但没有任何 API 使用它。这意味着&quot;每个用户可以自定义显示哪些营养指标&quot;的功能只完成了一半。</p><p><strong>教训</strong>：设计了但未实现的功能会在代码库中造成困惑——其他开发者会疑惑&quot;为什么有这个表但没 API&quot;。</p><ul><li>要么做完</li><li>要么删掉设计文档中的提及</li><li>要么标注 <code>TODO: not yet implemented</code></li></ul><h3 id="坑-4-对比功能的数据路径不统一" tabindex="-1">坑 4：对比功能的数据路径不统一 <a class="header-anchor" href="#坑-4-对比功能的数据路径不统一" aria-label="Permalink to &quot;坑 4：对比功能的数据路径不统一&quot;">​</a></h3><p><code>POST /api/v1/calculate</code>（对比功能）使用的是 legacy <code>food_nutrients</code> 表，而详情页使用的是新的代表值体系。两条数据路径的结果可能不一致。</p><p><strong>教训</strong>：新旧数据迁移期间要确保所有消费者 API 的数据路径一致，或者明确标注差异。</p><h3 id="坑-5-排名-评分的好友分享和社会化缺失" tabindex="-1">坑 5：排名/评分的好友分享和社会化缺失 <a class="header-anchor" href="#坑-5-排名-评分的好友分享和社会化缺失" aria-label="Permalink to &quot;坑 5：排名/评分的好友分享和社会化缺失&quot;">​</a></h3><p>排行榜目前是纯工具的视角——列出食物和分数。缺少&quot;你可以把这个排名分享给朋友&quot;或&quot;查看社区热议&quot;的社交维度。</p><p><strong>这不是 bug，是有意取舍</strong>：当前阶段聚焦数据质量和用户体验，社交功能放在后续路线图中。</p><hr><h2 id="五、对其他-ai-pm-的启发" tabindex="-1">五、对其他 AI PM 的启发 <a class="header-anchor" href="#五、对其他-ai-pm-的启发" aria-label="Permalink to &quot;五、对其他 AI PM 的启发&quot;">​</a></h2><h3 id="_1-数据质量-数据数量-是数据型产品的核心选择" tabindex="-1">1. &quot;数据质量 &gt; 数据数量&quot; 是数据型产品的核心选择 <a class="header-anchor" href="#_1-数据质量-数据数量-是数据型产品的核心选择" aria-label="Permalink to &quot;1. &quot;数据质量 &gt; 数据数量&quot; 是数据型产品的核心选择&quot;">​</a></h3><p>OpenFoodData 用权威等级、加权聚合、冲突检测、置信度系统建立了一套<strong>透明的数据质量体系</strong>。用户可以看到数据的&quot;信源&quot;和&quot;可信度&quot;，而不只是看到一串数字。</p><p>这提示我们：<strong>数据产品不只是提供数据，还要提供对数据的理解框架。</strong></p><h3 id="_2-评分体系的可解释性是信任的基础" tabindex="-1">2. 评分体系的可解释性是信任的基础 <a class="header-anchor" href="#_2-评分体系的可解释性是信任的基础" aria-label="Permalink to &quot;2. 评分体系的可解释性是信任的基础&quot;">​</a></h3><p>如果用户看到&quot;控糖友好分：7.2&quot;却不知道这个分数怎么来的，信任感会降低。OpenFoodData 用公开的公式让用户理解评分的构成——这个设计原则适用于任何涉及评分/评级的产品。</p><h3 id="_3-不做-清单比-要做-清单更有价值" tabindex="-1">3. &quot;不做&quot;清单比&quot;要做&quot;清单更有价值 <a class="header-anchor" href="#_3-不做-清单比-要做-清单更有价值" aria-label="Permalink to &quot;3. &quot;不做&quot;清单比&quot;要做&quot;清单更有价值&quot;">​</a></h3><p>明确不做条码扫描、不做饮食记录、不做医学建议——这些边界决定了产品的差异化定位。在 AI 产品领域，同质化竞争严重，<strong>敢于定义&quot;我不做什么&quot;往往比&quot;我做什么&quot;更能形成护城河。</strong></p><h3 id="_4-搜索范式决定产品气质" tabindex="-1">4. 搜索范式决定产品气质 <a class="header-anchor" href="#_4-搜索范式决定产品气质" aria-label="Permalink to &quot;4. 搜索范式决定产品气质&quot;">​</a></h3><p>标准品优先的搜索范式让 OpenFoodData 看起来像&quot;食物维基百科&quot;而非&quot;食物电商&quot;。搜索体验是用户对产品的第一印象——设计搜索时，想清楚你希望用户觉得&quot;这个产品是什么&quot;。</p>`,97)])])}const q=a(r,[["render",s]]);export{h as __pageData,q as default};
